            return $head . '<path d="M420 70v220M340 290h160" stroke="' . $b . '" stroke-opacity=".7" stroke-width="5" stroke-linecap="round"/><path d="M280 110h280" stroke="' . $b . '" stroke-opacity=".8" stroke-width="5" stroke-linecap="round"/><path d="M280 110l-44 90h88zM560 110l-44 90h88z" fill="none" stroke="' . $b . '" stroke-opacity=".5" stroke-width="3" stroke-linejoin="round"/><ellipse cx="280" cy="200" rx="44" ry="10" fill="#151513" stroke="' . $b . '" stroke-opacity=".6" stroke-width="3"/><ellipse cx="560" cy="200" rx="44" ry="10" fill="' . $o . '"/><circle cx="560" cy="170" r="14" fill="' . $o . '" fill-opacity=".6"/><text x="280" y="190" text-anchor="middle" font-family="Archivo, sans-serif" font-weight="800" font-size="26" fill="' . $b . '">$</text></svg>';
        case 'notebook':
            return $head . '<rect x="260" y="50" width="250" height="260" rx="18" fill="#151513" stroke="' . $b . '" stroke-opacity=".7" stroke-width="3"/><g fill="none" stroke="' . $b . '" stroke-opacity=".4" stroke-width="3" stroke-linecap="round"><path d="M290 110h190M290 150h190M290 190h120"/></g><g fill="' . $o . '"><rect x="290" y="226" width="80" height="14" rx="7"/></g><path d="M300 90l12 12 22-24" fill="none" stroke="' . $o . '" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" transform="translate(150 -6)"/><rect x="560" y="80" width="110" height="140" rx="12" fill="#151513" stroke="' . $b . '" stroke-opacity=".6" stroke-width="2"/><rect x="560" y="80" width="110" height="34" rx="12" fill="' . $o . '"/><g fill="' . $b . '" fill-opacity=".25"><circle cx="585" cy="150" r="6"/><circle cx="615" cy="150" r="6"/><circle cx="645" cy="150" r="6"/><circle cx="585" cy="180" r="6"/></g><path d="M630 175v34l24-8z" fill="' . $o . '"/></svg>';
        default: // bars
            return $head . '<g fill="none" stroke="' . $b . '" stroke-opacity=".9" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M120 300h600" stroke-opacity=".35"/><rect x="170" y="210" width="64" height="90" rx="8" fill="' . $o . '" fill-opacity=".25" stroke="' . $o . '"/><rect x="274" y="170" width="64" height="130" rx="8" fill="' . $o . '" fill-opacity=".35" stroke="' . $o . '"/><rect x="378" y="125" width="64" height="175" rx="8" fill="' . $o . '" fill-opacity=".5" stroke="' . $o . '"/><rect x="482" y="80" width="64" height="220" rx="8" fill="' . $o . '" stroke="' . $o . '"/><path d="M150 190l124-52 104 22 168-86" stroke-width="3"/></g></svg>';
